pub fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    condition
        .into_iter()
        .zip(x.into_iter())
        .zip(y.into_iter())
        .map(|((cond, xv), yv)| if cond { xv } else { yv })
        .collect()
}

